  ('structured_quantity_recognition_zr20', 'Zahlzerlegung / Schnelles Sehen', 'amber', 0, 'Strukturiertes Sehen bis 20', 'Structured quantity recognition up to 20', 'Das Kind erkennt strukturierte Mengen bis 20 auf einen Blick, ohne einzeln abzuzählen.', 'The child recognizes structured quantities up to 20 at a glance, without counting one by one.', 'A', 'structured_quantity_recognition'),
