  ('hundred_chart_navigation', 'Stellenwerte verstehen', 'indigo', 0, 'Hundertertafel: Struktur nutzen', '100-chart: use the row/column structure', 'Das Kind bestimmt eine fehlende Zahl auf der Hundertertafel über die Zeilen-/Spaltenstruktur.', 'The child determines a missing number on the hundred-chart using its row/column structure.', 'B', 'hundred_chart'),
  ('shift_plus_minus_1_2_zr10', 'Grundstrategien', 'emerald', 0, 'Um 1 oder 2 mehr/weniger', 'One or two more/fewer', 'Das Kind bestimmt eine Zahl, die um 1 oder 2 größer oder kleiner als eine gegebene Zahl ist.', 'The child determines a number that is 1 or 2 more or fewer than a given number.', 'C', 'shift_plus_minus'),
  ('compensation_strategy_zr20', 'Grundstrategien, Kombinierte Strategien', 'emerald', 0, 'Gegensinniges Verändern', 'Compensation strategy (+1/-1 keeps the sum)', 'Das Kind nutzt gegensinniges Verändern (z. B. +1 bei einem Summanden, -1 beim anderen), um eine Aufgabe zu vereinfachen.', 'The child uses a compensation strategy (e.g. +1 on one addend, -1 on the other) to simplify a task.', 'C', 'compensation_strategy'),
  ('even_odd_recognition', 'Grundstrategien', 'emerald', 0, 'Gerade und ungerade Zahlen', 'Even and odd numbers', 'Das Kind erkennt, ob eine Zahl gerade oder ungerade ist.', 'The child recognizes whether a number is even or odd.', 'C', 'even_odd'),
  ('fingerblitz_quantity_zr10', 'Grundstrategien', 'emerald', 0, 'Fingerblitz: Mengen an Fingern erkennen', 'Fingerblitz: quick finger-quantity recognition', 'Das Kind erkennt eine an den Fingern gezeigte Menge im ZR10 sofort, ohne einzeln nachzuzählen.', 'The child instantly recognizes a quantity shown on fingers within 10, without counting one by one.', 'C', 'fingerblitz'),
  ('equation_equivalence_zr20', 'Grundstrategien', 'emerald', 0, 'Gleichungen: Was ist gleich?', 'Equation equivalence', 'Das Kind erkennt, ob zwei Gleichungen im ZR20 den gleichen Wert ergeben.', 'The child recognizes whether two equations within 20 have the same value.', 'C', 'equation_equivalence'),
  ('commutativity_zr20', 'Grundstrategien', 'emerald', 0, 'Tauschaufgaben (Kommutativgesetz)', 'Commutativity', 'Das Kind erkennt, dass eine Tauschaufgabe (z. B. 3+5 und 5+3) das gleiche Ergebnis hat.', 'The child recognizes that a commuted task (e.g. 3+5 and 5+3) has the same result.', 'C', 'commutativity'),
  ('number_wall_zr20', 'Kombinierte Strategien', 'emerald', 0, 'Zahlenmauer', 'Number wall', 'Das Kind ergänzt eine Zahlenmauer im ZR20, indem es benachbarte Steine addiert oder eine fehlende Zahl erschließt.', 'The child completes a number wall within 20 by adding neighbouring blocks or working out a missing number.', 'C', 'number_wall'),
  ('calculation_triangle_zr20', 'Kombinierte Strategien', 'emerald', 0, 'Rechendreieck', 'Calculation triangle', 'Das Kind ergänzt ein Rechendreieck im ZR20, indem es die Beziehung zwischen den drei Zahlen nutzt.', 'The child completes a calculation triangle within 20 by using the relationship between the three numbers.', 'C', 'calculation_triangle'),
  ('magnitude_estimate_zr100', 'Kombinierte Strategien', 'emerald', 0, 'Zahlenblick: Größenschätzung ohne Rechnen', 'Magnitude estimation without computing', 'Das Kind schätzt die Größenordnung einer Zahl im ZR100, ohne sie exakt zu berechnen.', 'The child estimates the magnitude of a number within 100 without calculating it exactly.', 'C', 'magnitude_estimate'),
  ('ordinal_1', 'Ordinal Numbers', 'amber', 0, 'Ordnungszahlen verwenden', 'Use ordinal numbers', 'Das Kind verwendet Ordnungszahlen (z. B. der dritte), um die Position in einer Reihe zu benennen.', 'The child uses ordinal numbers (e.g. "the third") to name a position within a sequence.', 'A', 'ordinal'),
  ('representation_bild_symbol', 'Representation Networking', 'amber', 0, 'Bild und Symbol verknüpfen', 'Connect image and symbol', 'Das Kind verknüpft ein Bild mit dem passenden Zahlensymbol.', 'The child connects a picture with the matching number symbol.', 'A', 'representation_bild_symbol'),
  ('representation_bild_symbol_wort', 'Representation Networking', 'amber', 0, 'Bild, Symbol und Wort flexibel verknüpfen', 'Flexibly connect image, symbol and word', 'Das Kind verknüpft Bild, Zahlensymbol und Zahlwort flexibel miteinander, auch bei ähnlich klingenden Zahlwörtern (z. B. sechs/sechzehn/sechzig).', 'The child flexibly connects a picture, number symbol and number word, even for similar-sounding number words (e.g. six/sixteen/sixty).', 'A', 'representation_bild_symbol'),
  ('operation_sense_add', 'Operational Sense', 'violet', 0, 'Addition im Kontext verstehen', 'Understand addition in context', 'Das Kind erkennt in einer Sachsituation eine Additionshandlung und stellt sie als Rechnung dar.', 'The child recognizes an addition action in a story situation and expresses it as a calculation.', 'D', 'operation_sense'),
  ('operation_sense_sub', 'Operational Sense', 'violet', 0, 'Subtraktion im Kontext verstehen (wegnehmen und vergleichen)', 'Understand subtraction in context (take-away and compare)', 'Das Kind erkennt in einer Sachsituation eine Subtraktionshandlung (Wegnehmen oder Vergleichen) und stellt sie als Rechnung dar.', 'The child recognizes a subtraction action (taking away or comparing) in a story situation and expresses it as a calculation.', 'D', 'operation_sense'),
  ('operation_sense_story', 'Operational Sense', 'violet', 0, 'Rechengeschichten in Gleichungen übersetzen', 'Translate story problems into equations', 'Das Kind übersetzt eine Rechengeschichte in die passende Gleichung.', 'The child translates a story problem into the matching equation.', 'D', 'operation_sense'),
  ('number_line_rechenstrich', 'Advanced Number Line', 'indigo', 0, 'Rechenstrich zum Rechnen nutzen', 'Use the empty number line for calculation', 'Das Kind nutzt den leeren Rechenstrich, um eine Rechnung im ZR100 über gedankliche Sprünge zu lösen.', 'The child uses the empty number line to solve a calculation within 100 through mental jumps.', 'B', 'number_line_strategy'),
  ('number_line_zahlenstrahl', 'Advanced Number Line', 'indigo', 0, 'Zahlenstrahl zur Positionierung nutzen (Mitte finden)', 'Use the marked number line for positioning (find the midpoint)', 'Das Kind nutzt den beschrifteten Zahlenstrahl, um die Mitte zwischen zwei Zahlen im ZR100 zu bestimmen.', 'The child uses the labelled number line to find the midpoint between two numbers within 100.', 'B', 'number_line_strategy'),
  ('number_line_strategies', 'Advanced Number Line', 'indigo', 0, 'Zahlenstrahl-Strategien: Zahl über Ungleichungen eingrenzen', 'Number-line strategies: narrow a number via inequalities', 'Das Kind grenzt eine gesuchte Zahl im ZR100 über Ungleichungen auf dem Zahlenstrahl ein.', 'The child narrows down a target number within 100 on the number line using inequalities.', 'B', 'number_line_strategy'),
  ('bundling_recognition_overflow_zr100', 'Stellenwerte verstehen', 'indigo', 0, 'Bündelung erkennen bei mehr als 10 Einern', 'Recognize bundling when there are more than 10 loose ones', 'Das Kind erkennt bei einer Dienes-Darstellung mit mehr als 10 losen Einern, dass diese zu einem weiteren Zehner gebündelt werden müssen.', 'The child recognizes, in a base-ten block display with more than 10 loose ones, that these must be bundled into another ten.', 'B', 'bundling_recognition'),
  ('hundred_chart_structure_zr100', 'Stellenwerte verstehen', 'indigo', 0, 'Hundertertafel: Struktur nutzen (oben/unten/links/rechts)', '100-chart: use the row/column structure (above/below/left/right)', 'Das Kind bestimmt einen Nachbarwert auf einer spärlich beschrifteten Hundertertafel über die +/-1 (Zeile) bzw. +/-10 (Spalte) Struktur.', 'The child determines a neighbouring value on a sparsely labelled hundred-chart using the +/-1 (row) or +/-10 (column) structure.', 'B', 'hundred_chart')
  on conflict (id) do nothing;

