  ('00000000-0000-0000-0000-000000000003', 43, 'image', 'Wie viele Punkte siehst du im Hunderterfeld?', 'How many dots do you see in the hundred-field?', 'single', '"97"'::jsonb, ARRAY['dot_field_near_max'], NULL, 'v3 legacy-derived (iMINT Testkarte 12); requires "what''s missing" reasoning, qualitatively harder than the other three dot-field items', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 44, 'image', 'Zähle die Zehnerstangen und die Einerwürfel. Wie viele sind das insgesamt?', 'Count the tens rods and the ones cubes. How many are there altogether?', 'single', '"47"'::jsonb, ARRAY['bundling_recognition_zr100'], NULL, 'v3 legacy-derived (iMINT Testkarte 10); item a of 2; supersedes clean-room v1 LN21 (bundled sticks, same "count bundles then singles, name the total" construct); draft German wording said "Punkte" (dots) -- copy-paste leftover from the dot-based items, corrected here since the widget shows Dienes rods/cubes, not dots', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 45, 'image', 'Zähle die Zehnerstangen und die Einerwürfel. Wie viele sind das insgesamt?', 'Count the tens rods and the ones cubes. How many are there altogether?', 'single', '"63"'::jsonb, ARRAY['bundling_recognition_zr100'], NULL, 'v3 legacy-derived (iMINT Testkarte 10); item b of 2', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 46, 'image', 'Zähle die Zehnerstangen und die Einerwürfel. Wie viele sind das insgesamt?', 'Count the tens rods and the ones cubes. How many are there altogether?', 'single', '"53"'::jsonb, ARRAY['bundling_recognition_overflow_zr100'], NULL, 'added 2026-09-12 per Jakob''s feedback: 4 rods + 13 loose ones (more than 10 unbundled ones) to see whether the child still just counts/adds everything rather than assuming the ones pile must be single-digit', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 47, 'image', 'Im Hundertfeld ist die 47 markiert. Was steht direkt über der 47?', 'In the hundred-chart, 47 is marked. What is directly above 47?', 'single', '"37"'::jsonb, ARRAY['hundred_chart_structure_zr100'], NULL, 'added 2026-09-12 per Jakob''s feedback: sparse hundred-chart (only the four corners + the marked number visible) -- item a of 4 (above); the answer cell is never itself shown, so it must be derived from the ±10 column structure, not read off a labeled neighbor', 'core', NULL),
