  ('00000000-0000-0000-0000-000000000003', 89, 'image', 'In der Zahlenmauer ist jeder Stein die Summe der zwei Steine darunter (siehe Bild). Was steht ganz oben?', 'In the number wall, each stone is the sum of the two stones below it (see picture). What is at the very top?', 'single', '"17"'::jsonb, ARRAY['number_wall_zr20'], NULL, 'v3 legacy-derived (Kombi-Arbeitskarte 9 gap skill; step-3 cross-check); base 4+5=9, 5+3=8, 9+8=17; static widget for now, Jakob asked for an eventual animated +/arrow build-up', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 90, 'image', 'Im Rechendreieck zeigt jede Seite die Summe der beiden Ecken, die sie verbindet (siehe Bild). Was zeigt die untere Seite?', 'In the calculation triangle, each side shows the sum of the two corners it connects (see picture). What does the bottom side show?', 'single', '"10"'::jsonb, ARRAY['calculation_triangle_zr20'], NULL, 'v3 legacy-derived (Kombi-Arbeitskarte 10 gap skill; step-3 cross-check); 6+4=10; static widget for now, same animation caveat as the number wall', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 91, 'text', 'Wenn 7 + 5 = 12 ist, wie viel ist 8 + 4?', 'If 7 + 5 = 12, how much is 8 + 4?', 'single', '"12"'::jsonb, ARRAY['compensation_strategy_zr20'], NULL, 'v3 legacy-derived (Arbeitskarte 6 / Kombi-Arbeitskarte 7 gap skill; step-3 cross-check); tests the compensation insight (+1/-1 keeps the sum)', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 92, 'text', 'Ist 14 gerade oder ungerade?', 'Is 14 even or odd?', 'single', '"gerade"'::jsonb, ARRAY['even_odd_recognition'], NULL, 'v3 legacy-derived (Arbeitskarte 15 gap skill; step-3 cross-check); item a of 2', 'core', NULL),
