  ('00000000-0000-0000-0000-000000000003', 94, 'image', 'Du siehst kurz Finger. Wie viele waren es?', 'You''ll briefly see fingers. How many were there?', 'single', '"8"'::jsonb, ARRAY['fingerblitz_quantity_zr10'], NULL, 'v3 legacy-derived (Arbeitskarte 1 gap skill; step-3 cross-check); uses the existing finger-image assets (assets/images/fingers/) via FingerBildWidget, flashed with the same Bereit/countdown/flash pattern as A2.1-01', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 95, 'text', 'Stimmt das? 6 + 4 = 8 + 2', 'Is this correct? 6 + 4 = 8 + 2', 'single', '"ja"'::jsonb, ARRAY['equation_equivalence_zr20'], NULL, 'v3 legacy-derived (Arbeitskarte 18 gap skill; step-3 cross-check); item a of 2 (true case, 10 = 10)', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 96, 'text', 'Stimmt das? 9 + 3 = 8 + 5', 'Is this correct? 9 + 3 = 8 + 5', 'single', '"nein"'::jsonb, ARRAY['equation_equivalence_zr20'], NULL, 'v3 legacy-derived (Arbeitskarte 18 gap skill; step-3 cross-check); item b of 2 (false case, 12 != 13)', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 97, 'text', 'Wenn 8 + 5 = 13 ist, wie viel ist 5 + 8?', 'If 8 + 5 = 13, how much is 5 + 8?', 'single', '"13"'::jsonb, ARRAY['commutativity_zr20'], NULL, 'v3 legacy-derived (Arbeitskarte 19 gap skill; step-3 cross-check); caveat -- can''t distinguish reuse of the given fact from recomputing', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 98, 'text', 'Ist 47 + 38 größer oder kleiner als 100?', 'Is 47 + 38 greater or less than 100?', 'single', '"kleiner"'::jsonb, ARRAY['magnitude_estimate_zr100'], NULL, 'v3 legacy-derived (Kombi-Arbeitskarte 11/13 gap skill; step-3 cross-check); 47+38=85, tests estimation without needing the exact sum', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 99, 'text', 'Ein Zug hat 6 Wagen. Der 4. Wagen ist rot. Wie viele Wagen sind vor dem roten Wagen?', 'A train has 6 carriages. The 4th carriage is red. How many carriages are in front of the red one?', 'single', '"3"'::jsonb, ARRAY['ordinal_1'], NULL, 'PIKAS-sourced (Kartei 9); step-3 addition; ordinal_2 was rejected by Jakob (children don''t know/need the word "Ordnungszahl"), this one survives since it doesn''t require that vocabulary', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 100, 'text', 'Welches Wort passt zur Zahl 6?', 'Which word matches the number 6?', 'single', '"sechs"'::jsonb, ARRAY['representation_bild_symbol_wort'], NULL, 'PIKAS-sourced (Kartei 39); tests the sechs/sechzehn/sechzig confusion; tap options curated in kAnswerSpecs (LN703) since choiceOptionsOf can''t derive an arbitrary three-word list from prose; the options themselves were dropped from the question text once buttons carried them (Jakob''s 2026-09-13 feedback)', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 101, 'text', 'Auf dem einen Teller liegen 7 Kirschen, auf dem anderen 4. Wie viel mehr Kirschen liegen auf dem einen Teller?', 'On one plate there are 7 cherries, on the other 4. How many more cherries are on the one plate?', 'single', '"3"'::jsonb, ARRAY['compare_quantity_difference'], NULL, 'v3 legacy-derived (iMINT Testkarte 14)', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 102, 'text', 'Auf der Wiese sitzen 4 Vögel. 3 weitere Vögel kommen dazu. Wie viele Vögel sitzen jetzt auf der Wiese?', '4 birds are sitting in the meadow. 3 more birds join them. How many birds are in the meadow now?', 'single', '"7"'::jsonb, ARRAY['operation_sense_add'], NULL, 'PIKAS-sourced (Kartei 44); step-3 addition', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 103, 'text', 'Auf dem Teller liegen 8 Kekse. Du isst 3 davon. Wie viele Kekse liegen noch auf dem Teller?', 'There are 8 cookies on the plate. You eat 3 of them. How many cookies are left on the plate?', 'single', '"5"'::jsonb, ARRAY['operation_sense_sub'], NULL, 'PIKAS-sourced (Kartei 38); item a of 2 (wegnehmen / take-away)', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 104, 'text', 'Lisa hat 9 Sticker, Tom hat 6 Sticker. Wie viele Sticker hat Lisa mehr als Tom?', 'Lisa has 9 stickers, Tom has 6 stickers. How many more stickers does Lisa have than Tom?', 'single', '"3"'::jsonb, ARRAY['operation_sense_sub'], NULL, 'PIKAS-sourced (Kartei 38); item b of 2 (vergleichen / compare) -- same skill as 705, different construct (comparison vs. take-away)', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 105, 'text', 'Welche Rechnung passt zur Geschichte? Mia hatte 5 Bonbons und bekommt noch 4 dazu.', 'Which calculation matches the story? Mia had 5 candies and gets 4 more.', 'single', '"5+4"'::jsonb, ARRAY['operation_sense_story'], NULL, 'PIKAS-sourced (Kartei 42); tests translation to an equation, not computation -- grades on the typed equation "5+4", not the result 9; the a)/b)/c) list was dropped from the question text once buttons carried the options (Jakob''s 2026-09-13 feedback)', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 106, 'image', 'Du startest bei 36 auf dem Rechenstrich, springst 10 Schritte zurück und dann noch 4 Schritte zurück. Bei welcher Zahl landest du?', 'You start at 36 on the empty number line, jump 10 steps back and then 4 more steps back. Which number do you land on?', 'single', '"22"'::jsonb, ARRAY['number_line_rechenstrich'], NULL, 'PIKAS-sourced (Kartei 45); step-3 addition; renders as a RechenstrichWidget (start 36, jumps -10/-4) instead of bare text, per Jakob''s 2026-09-13 feedback (''for questions about a Rechenstrich, we should show a Rechenstrich'')', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 107, 'image', 'Auf dem Rechenstrich stehen 20 und 40. Welche Zahl liegt genau in der Mitte?', 'On the number line, 20 and 40 are marked. Which number is exactly in the middle?', 'single', '"30"'::jsonb, ARRAY['number_line_zahlenstrahl'], NULL, 'PIKAS-sourced (Kartei 11/13); renders as a RechenstrichWidget-style line with only the two endpoints labeled and a downward arrow pointing at the midpoint, per Jakob''s 2026-09-13 feedback', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 108, 'text', 'Eine Zahl ist größer als 34 und kleiner als 36. Welche Zahl ist es?', 'A number is greater than 34 and less than 36. Which number is it?', 'single', '"35"'::jsonb, ARRAY['number_line_strategies'], NULL, 'PIKAS-sourced (Kartei 27); tightened to a single solution since the source game''s own example is open-ended', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 109, 'image', 'Auf dem Zahlenstrahl von 0 bis 20 ist eine Stelle markiert. Welche Zahl ist das?', 'A point is marked on the number line from 0 to 20. Which number is it?', 'single', '"14"'::jsonb, ARRAY['place_on_numberline_zr20'], NULL, 'iMINT-gap skill (Arbeitskarte 10); renders as a NumberLineReadWidget (0-20, mark at 14, unlabeled) -- reading a marked position off a scaled line, the opposite interaction from the tap-to-place Zahlenstrahl widgets used elsewhere in the app', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 110, 'image', 'Auf dem Zahlenstrahl von 0 bis 100 ist eine Stelle markiert. Welche Zahl ist das?', 'A point is marked on the number line from 0 to 100. Which number is it?', 'single', '"68"'::jsonb, ARRAY['place_on_numberline_zr100'], NULL, 'iMINT-gap skill (Arbeitskarte 11); renders as a NumberLineReadWidget (0-100, mark at 68, unlabeled)', 'core', NULL),
  ('00000000-0000-0000-0000-000000000003', 111, 'text', 'Du hörst gleich fünf Zahlen nacheinander. Schreibe jede Zahl in der richtigen Reihenfolge auf. Du kannst sie dir so oft anhören, wie du möchtest.', 'You''ll hear five numbers, one after another. Write each number down in order. You can listen to them again as many times as you like.', 'single', '"17, 47, 70, 72, 84"'::jsonb, ARRAY['number_word_dictation_zr100'], NULL, 'iMINT-gap skill (Testkarte 4, Zahlen hören und schreiben); one audio clip speaks all 5 numbers in sequence (17, 47, 70, 72, 84 -- a mix of a teen number, a decade number and three distinct-digit two-digit numbers, per Jakob''s 2026-09-13 selection); the child types each into its own box in order via the sequence answer mode; a replay button (existing _buildAudioReplayButton wiring) lets the child re-listen as often as needed', 'core', 'Research/zahlen_diktat_17_47_70_72_84.mp3')
  on conflict (diagnostic_id, question_number) do nothing;
